import math

class OneTwo:

	def __init__(self, x):
		self.first = x[0]
		self.second = x[1]
		self.nothing = False if self.first else True

	def pows_second(self, n):
		n = math.floor(math.log(n) / math.log(2))
		return n if n <= self.second else 0

	def end_point(self):
		ad = self.first * 1
		mul = 2 ** self.second
		mul = 0 if mul == 1 else mul
		return ad + mul

	def second_multiply(self, n, available_second):
		second_multiply = n // 2
		return second_multiply if second_multiply <= available_second else available_second

	def first_multiply(self, n):
		return n if n <= self.first else self.first

	def begin_p(self):
		return self.first + 1 if self.first > self.second * 2 else self.second * 2 + 1

	def res_step(self):
		if self.nothing:
			return self.second * 2 / 2
		elif self.first > self.second * 2:
			return self.first
		else:
			return self.second * 2

	def res_count(self):
		end_point = self.end_point()
		result = 0
		begin_p = 1
		result = self.res_step()
		begin_p = self.begin_p()
		n = begin_p
		while n <= end_point:
			powers_second = self.pows_second(n)
			powers_second_result = 2 ** powers_second if powers_second != 0 else 0
			remaining = n - powers_second_result
			available_second = self.second - powers_second
			if remaining > 0:
				remaining -= 2 * self.second_multiply(remaining, available_second)
				remaining -= self.first_multiply(remaining)
			if remaining == 0:
				result += 1
			n += 1
		return int(result)
t = int(input())
a_b = [[int(i) for i in input().strip().split(' ')] for x in range(t)]
for x in a_b:
	inst = OneTwo(x)
	print(inst.res_count())
